/* @lc app=leetcode id=3985 lang=kotlin */ class Solution { fun man(t: IntArray): IntArray = IntArray(t.size).also { p -> t.indices.fold(0 to -1) { (c, r), i -> (if (i <= r) minOf(p[2 * c - i], r - i) else 0).let { k0 -> generateSequence(k0) { it + 1 }.first { k -> !(i - k - 1 >= 0 && i + k + 1 < t.size && t[i - k - 1] == t[i + k + 1]) }.let { k -> p.set(i, k).let { if (i + k > r) i to i + k else c to r } } } } } fun getSum(nums: IntArray): Long = IntArray(2 * nums.size + 1) { if (it % 2 == 1) nums[it / 2] else 0 }.let { t -> man(t).let { p -> t.runningFold(0L) { a, b -> a + b }.let { P -> t.indices.maxOf { i -> P[i + p[i] + 1] - P[i - p[i]] } } } } }